-- DDL
CREATE TABLE customers (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE customers ADD COLUMN city VARCHAR(60) NULL;

-- DML
INSERT INTO customers (name, email) VALUES ('Asha', 'asha@example.com');
UPDATE customers SET city = 'Pune' WHERE id = 1;
DELETE FROM customers WHERE id = 1;

-- DCL
GRANT SELECT, INSERT ON shop.* TO 'app'@'localhost';

CREATE INDEX idx_orders_customer ON orders (customer_id);
CREATE UNIQUE INDEX uq_users_email ON users (email);
CREATE INDEX idx_orders_status_created ON orders (status, created_at);

SHOW INDEX FROM orders;

-- Not sargable: function on the column prevents index use
SELECT * FROM orders WHERE YEAR(created_at) = 2025;

-- Sargable: range on the bare column
SELECT * FROM orders
WHERE created_at >= '2025-01-01' AND created_at < '2026-01-01';

CREATE INDEX idx_orders_lookup ON orders (customer_id, status, created_at);

-- Uses all three parts, and returns rows already sorted
SELECT id, total
FROM orders
WHERE customer_id = 42 AND status = 'paid'
ORDER BY created_at DESC
LIMIT 10;

-- Cannot seek with this index: leftmost column missing
SELECT id FROM orders WHERE status = 'paid';

CREATE TABLE users (
    id       BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email    VARCHAR(150) NOT NULL,
    phone    VARCHAR(20)  NULL,
    UNIQUE KEY uq_users_email (email),
    UNIQUE KEY uq_users_phone (phone)   -- many rows may have NULL phone
);

CREATE TABLE role_user (
    user_id BIGINT UNSIGNED NOT NULL,
    role_id BIGINT UNSIGNED NOT NULL,
    PRIMARY KEY (user_id, role_id)
);

-- After normalisation to 3NF
CREATE TABLE customers  (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(100), city VARCHAR(60));
CREATE TABLE products   (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(150), price INT UNSIGNED);
CREATE TABLE orders     (id BIGINT UNSIGNED PRIMARY KEY, customer_id BIGINT UNSIGNED, created_at DATETIME);
CREATE TABLE order_items (
    order_id   BIGINT UNSIGNED,
    product_id BIGINT UNSIGNED,
    qty        INT UNSIGNED,
    price      INT UNSIGNED,          -- price when ordered (a snapshot, not redundancy)
    PRIMARY KEY (order_id, product_id)
);

START TRANSACTION;

SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;   -- lock the row

UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;

INSERT INTO transfers (from_id, to_id, amount) VALUES (1, 2, 500);

COMMIT;      -- or ROLLBACK; if anything failed

SELECT table_name, engine
FROM information_schema.tables
WHERE table_schema = DATABASE();

ALTER TABLE legacy_logs ENGINE = InnoDB;
